import React, { useState } from 'react';
import { TabMenu } from 'primereact/tabmenu';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="tabMenu-accessibility">Accessible TabMenu</label>
            <TabMenu 
                id="tabMenu-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible TabMenu input"
                placeholder="Enter tabMenu"
            />
        </div>
    );
}